import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Days Asia- State of the Cephalopod with Josh Durgin (IBM)","description":"","frontmatter":{"title":"Ceph Days Asia- State of the Cephalopod with Josh Durgin (IBM)","date":"2024-10-03T00:00:00.000Z","updated":"2024-10-03T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","高可用性","可扩展性","对象存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_Days_Asia_-_State_of_the_Cephalopod_with_Josh_Durgin_IBM.md","filePath":"posts/2024/Ceph_Days_Asia_-_State_of_the_Cephalopod_with_Josh_Durgin_IBM.md","lastUpdated":1780459816000}'),o={name:"posts/2024/Ceph_Days_Asia_-_State_of_the_Cephalopod_with_Josh_Durgin_IBM.md"};function h(s,e,p,_,r,n){return l(),i("div",null,[...e[0]||(e[0]=[t('<p>Ceph Days Asia 会议纪要</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>本次会议在韩国举行，主题聚焦于Ceph项目的最新进展和社区动态。会议回顾了2023年在Asan举办的CephDay活动，强调了社区成员面对面交流的重要性。此外，还提到了即将在日内瓦举行的CephDay活动。</p><h3 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h3><ol><li><p><strong>Ceph的使用情况</strong>：</p><ul><li>通过Thum系统收集的数据显示，Ceph集群已使用超过1.5 Exabytes的数据，且数据量持续增长。</li><li>介绍了最新版本Reef的发布情况，以及即将到来的下一个主要版本。</li></ul></li><li><p><strong>社区发展</strong>：</p><ul><li>Ceph基金会与开发者及用户的合作，通过用户委员会建立更直接的反馈机制。</li><li>持续的开放会议和与学生的互动，如通过Google Summer of Code等项目。</li><li>基金会的新成员结构，包括Bloomberg、IBM和45 drives等新加入的钻石会员。</li></ul></li><li><p><strong>Ceph的技术特点</strong>：</p><ul><li>Ceph作为一个统一存储系统，支持对象存储、块存储和文件系统存储。</li><li>强调Ceph的高可靠性和可扩展性，以及其在数据一致性和分区容忍性方面的优势。</li><li>详细介绍了Ceph的底层存储系统RADOS，以及其如何通过CRUSH算法确保数据分布和故障恢复。</li></ul></li><li><p><strong>未来发展方向</strong>：</p><ul><li>性能优化，特别是在大规模环境下的性能一致性。</li><li>提高易用性，简化管理和操作流程。</li><li>扩展协议支持，如支持更多标准化的存储协议。</li><li>优化存储效率，特别是在纠删码技术上的改进。</li></ul></li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>继续加强Ceph社区的建设和用户反馈机制。</li><li>推动Ceph在性能、易用性和协议支持方面的持续改进。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h3><ul><li>继续举办CephDay等活动，加强社区成员的交流和合作。</li><li>发布新版本的Ceph，并持续优化其功能和性能。</li><li>加强文档和用户支持，提高Ceph的易用性和用户满意度。</li></ul><h3 id="其他信息" tabindex="-1">其他信息 <a class="header-anchor" href="#其他信息" aria-label="Permalink to &quot;其他信息&quot;">​</a></h3><ul><li>Ceph的开发完全开放，所有代码托管在GitHub上，欢迎社区成员参与贡献。</li><li>Ceph基金会将继续支持项目的发展，包括技术开发、社区活动和基础设施支持。</li></ul>',11)])])}const C=a(o,[["render",h]]);export{u as __pageData,C as default};
